func (h *checkout) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	req, err := decodeCheckout(r)          // one task per step, named for intent
	if err != nil { fail(w, http.StatusBadRequest, err); return }
	total, err := totalFor(req.Items, req.Coupon)
	if err != nil { fail(w, http.StatusUnprocessableEntity, err); return }
	charge, err := h.payments.Charge(r.Context(), req.UserID, total)
	if err != nil { fail(w, http.StatusPaymentRequired, err); return }
	writeCreated(w, charge)
}
